import Foundation

/// NEMSIS v3.5.1 EMSDataSet export, generated by code from events only.
/// UNVALIDATED until it passes the NEMSIS XSD + Schematron (see docs).
/// Elements we cannot fill from what was heard are omitted (or nil +
/// NV="7701003" Not Recorded where the element is required).
public enum NEMSISExport {
    public static let unvalidatedBanner = "UNVALIDATED: generated by Earshot; not yet checked against the NEMSIS v3.5.1 XSD/Schematron."
    static let notRecorded = #"xsi:nil="true" NV="7701003""#

    public static func render(_ m: ChartModel, events: [EarshotEvent], dict: EMSDictionary, softwareVersion: String = "0.1.0") -> RenderedDoc {
        var x: [String] = []
        func esc(_ s: String) -> String {
            s.replacingOccurrences(of: "&", with: "&amp;").replacingOccurrences(of: "<", with: "&lt;")
                .replacingOccurrences(of: ">", with: "&gt;").replacingOccurrences(of: "\"", with: "&quot;")
        }
        func dt(_ e: EarshotEvent) -> String { e.time }
        x.append(#"<?xml version="1.0" encoding="UTF-8"?>"#)
        x.append("<!-- \(unvalidatedBanner) -->")
        x.append("<!-- Every element below cites the Earshot event it came from. -->")
        x.append(#"<EMSDataSet xmlns="http://www.nemsis.org" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:schemaLocation="http://www.nemsis.org https://nemsis.org/media/nemsis_v3/release-3.5.1/XSDs/NEMSIS_XSDs/EMSDataSet_v3.xsd">"#)
        x.append("  <Header>")
        x.append("    <DemographicGroup>")
        x.append("      <dAgency.01>NOT_SET</dAgency.01>")
        x.append("      <dAgency.02>NOT_SET</dAgency.02>")
        x.append("      <dAgency.04>NOT_SET</dAgency.04>")
        x.append("    </DemographicGroup>")
        x.append("    <PatientCareReport UUID=\"\(esc(uuid(m.callId)))\">")
        x.append("      <eRecord>")
        x.append("        <eRecord.01>\(esc(m.callId))</eRecord.01>")
        x.append("        <eRecord.SoftwareApplicationGroup>")
        x.append("          <eRecord.02>Earshot</eRecord.02>")
        x.append("          <eRecord.03>Earshot</eRecord.03>")
        x.append("          <eRecord.04>\(softwareVersion)</eRecord.04>")
        x.append("        </eRecord.SoftwareApplicationGroup>")
        x.append("      </eRecord>")
        x.append("      <eTimes>")
        if let a = m.arrival {
            x.append("        <!-- \(a.id): arrival, \(a.fields["method"] ?? "") -->")
            x.append("        <eTimes.11>\(dt(a))</eTimes.11>")
        } else { x.append("        <eTimes.11 \(notRecorded)/>") }
        if let h = m.handoff {
            x.append("        <!-- \(h.id): transfer of care, \(h.fields["method"] ?? "") -->")
            x.append("        <eTimes.12>\(dt(h))</eTimes.12>")
        } else { x.append("        <eTimes.12 \(notRecorded)/>") }
        if let w = m.wallTimeMs { x.append("        <!-- wall time = eTimes.12 - eTimes.11 = \(w / 1000) s -->") }
        x.append("      </eTimes>")
        x.append("      <ePatient>")
        if let a = m.age, let _ = Int(a.text) {
            x.append("        <!-- \(a.events.joined(separator: ",")) -->")
            x.append("        <ePatient.AgeGroup>")
            x.append("          <ePatient.15>\(a.text)</ePatient.15>")
            x.append("          <ePatient.16>2516009</ePatient.16>")
            x.append("        </ePatient.AgeGroup>")
        }
        if let s = m.sex {
            let code = s.text == "male" ? "9919003" : s.text == "female" ? "9919001" : "9919005"
            x.append("        <ePatient.25>\(code)</ePatient.25><!-- \(s.events.joined(separator: ",")) -->")
        }
        x.append("      </ePatient>")
        if !m.vitals.isEmpty {
            x.append("      <eVitals>")
            for v in m.vitals {
                let f = v.fields
                x.append("        <eVitals.VitalGroup><!-- \(v.id) -->")
                x.append("          <eVitals.01>\(dt(v))</eVitals.01>")
                x.append("          <eVitals.02>9923001</eVitals.02>")
                if let s = f["bp_systolic"] {
                    x.append("          <eVitals.BloodPressureGroup>")
                    x.append("            <eVitals.06>\(s)</eVitals.06>")
                    if let d = f["bp_diastolic"] { x.append("            <eVitals.07>\(d)</eVitals.07>") }
                    if f["bp_method"] == "palpation" { x.append("            <eVitals.08>3308009</eVitals.08><!-- cuff-manual palpated only -->") }
                    x.append("          </eVitals.BloodPressureGroup>")
                }
                if let hr = f["heart_rate"] { x.append("          <eVitals.HeartRateGroup><eVitals.10>\(hr)</eVitals.10></eVitals.HeartRateGroup>") }
                if let s = f["spo2"] { x.append("          <eVitals.12>\(s)</eVitals.12>") }
                if let r = f["resp_rate"] { x.append("          <eVitals.14>\(r)</eVitals.14>") }
                if let e = f["etco2"] { x.append("          <eVitals.16>\(e)</eVitals.16>") }
                if let g = f["glucose"], Int(g) != nil { x.append("          <eVitals.18>\(g)</eVitals.18>") }
                if let g = f["gcs"] { x.append("          <eVitals.GlasgowScoreGroup><eVitals.23>\(g)</eVitals.23></eVitals.GlasgowScoreGroup>") }
                if let t = f["temp"], let d = Double(t) {
                    let c = d > 50 ? ((d - 32) * 5 / 9 * 10).rounded() / 10 : d
                    x.append("          <eVitals.TemperatureGroup><eVitals.24>\(c)</eVitals.24></eVitals.TemperatureGroup>")
                }
                if let p = f["pain"] { x.append("          <eVitals.PainScaleGroup><eVitals.27>\(p)</eVitals.27></eVitals.PainScaleGroup>") }
                x.append("        </eVitals.VitalGroup>")
            }
            x.append("      </eVitals>")
        }
        if !m.meds.isEmpty {
            x.append("      <eMedications>")
            for e in m.meds {
                let f = e.fields
                let drug = f["drug"].flatMap { dict.drug(named: $0) }
                x.append("        <eMedications.MedicationGroup><!-- \(e.id): \(esc(f["drug"] ?? "")) -->")
                x.append("          <eMedications.01>\(dt(e))</eMedications.01>")
                x.append("          <eMedications.02>9923001</eMedications.02>")
                if let rx = drug?.rxcui { x.append("          <eMedications.03 CodeType=\"9924003\">\(rx)</eMedications.03>") }
                else { x.append("          <eMedications.03 \(notRecorded)/>") }
                if let r = f["route"], let code = dict.formulary.routes[r]?.nemsis_code { x.append("          <eMedications.04>\(code)</eMedications.04>") }
                else { x.append("          <eMedications.04 \(notRecorded)/>") }
                if let d = f["dose"] {
                    x.append("          <eMedications.DosageGroup>")
                    x.append("            <eMedications.05>\(d)</eMedications.05>")
                    if let u = f["unit"], let code = dict.formulary.units[u]?.nemsis_code {
                        x.append("            <eMedications.06>\(code)</eMedications.06>" + (e.receipts?["unit"]?.inferred != nil ? "<!-- unit inferred from protocol, confirm -->" : ""))
                    } else { x.append("            <eMedications.06 \(notRecorded)/>") }
                    x.append("          </eMedications.DosageGroup>")
                }
                x.append("        </eMedications.MedicationGroup>")
            }
            x.append("      </eMedications>")
        }
        if !m.procedures.isEmpty {
            x.append("      <eProcedures>")
            for e in m.procedures {
                x.append("        <eProcedures.ProcedureGroup><!-- \(e.id): \(esc(e.fields["procedure"] ?? "")); SNOMED code not mapped yet -->")
                x.append("          <eProcedures.01>\(dt(e))</eProcedures.01>")
                x.append("          <eProcedures.02>9923001</eProcedures.02>")
                x.append("          <eProcedures.03 \(notRecorded)/>")
                x.append("        </eProcedures.ProcedureGroup>")
            }
            x.append("      </eProcedures>")
        }
        x.append("      <eNarrative>")
        x.append("        <eNarrative.01>\(esc(narrative(m)))</eNarrative.01>")
        x.append("      </eNarrative>")
        x.append("    </PatientCareReport>")
        x.append("  </Header>")
        x.append("</EMSDataSet>")
        return RenderedDoc(name: "nemsis.xml", text: x.joined(separator: "\n") + "\n")
    }

    static func narrative(_ m: ChartModel) -> String {
        Renderers.chart(m).text.replacingOccurrences(of: "**", with: "")
    }

    /// Deterministic UUID-shaped id from the call id (FNV-1a based).
    static func uuid(_ s: String) -> String {
        var h1: UInt64 = 0xcbf29ce484222325, h2: UInt64 = 0x84222325cbf29ce4
        for b in s.utf8 { h1 = (h1 ^ UInt64(b)) &* 0x100000001b3; h2 = (h2 ^ UInt64(b)) &* 0x100000001b3 &+ 7 }
        let hex = String(format: "%016llx%016llx", h1, h2)
        let c = Array(hex)
        return "\(String(c[0..<8]))-\(String(c[8..<12]))-4\(String(c[13..<16]))-a\(String(c[17..<20]))-\(String(c[20..<32]))"
    }
}
